package com.hospital.system.repository; import com.hospital.system.model.Appointment; import java.util.*; import org.springframework.jdbc.core.*; import org.springframework.stereotype.Repository; @Repository public class AppointmentRepository { private final JdbcTemplate db; public AppointmentRepository(JdbcTemplate db){this.db=db;} private final RowMapper<Appointment> m=(r,n)->{Appointment a=new Appointment();a.appointmentId=r.getLong("appointment_id");a.patientId=r.getLong("patient_id");a.doctorId=r.getLong("doctor_id");a.patientName=r.getString("patient_name");a.doctorName=r.getString("doctor_name");a.departmentName=r.getString("department_name");a.appointmentDate=r.getObject("appointment_date",java.time.LocalDate.class);a.appointmentTime=r.getObject("appointment_time",java.time.LocalTime.class);a.reason=r.getString("reason");a.status=r.getString("status");a.createdAt=r.getTimestamp("created_at").toLocalDateTime();return a;}; public List<Appointment> all(){return db.query("SELECT * FROM v_appointment_details ORDER BY appointment_date DESC,appointment_time DESC",m);} public Optional<Appointment> one(Long id){return db.query("SELECT * FROM v_appointment_details WHERE appointment_id=?",m,id).stream().findFirst();} public boolean existsSlot(Long d,java.time.LocalDate date,java.time.LocalTime time){return Boolean.TRUE.equals(db.queryForObject("SELECT COUNT(*)>0 FROM appointment WHERE doctor_id=? AND appointment_date=? AND appointment_time=? AND status<>'CANCELLED'",Boolean.class,d,date,time));} public int add(Appointment a){return db.update("INSERT INTO appointment(patient_id,doctor_id,appointment_date,appointment_time,reason,status) VALUES(?,?,?,?,?,'BOOKED')",a.patientId,a.doctorId,a.appointmentDate,a.appointmentTime,a.reason);} public int status(Long id,String status){return db.update("UPDATE appointment SET status=? WHERE appointment_id=?",status,id);} public int delete(Long id){return db.update("DELETE FROM appointment WHERE appointment_id=?",id);} }
